package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import android.content.*;import com.insight.quantlife.*;import org.json.*;

/** UI retries, composer routing, layout and isolated-browser checks with synthetic responses. */
public class FeishuUiTest extends DocumentEditorTest {
 JSONObject sample()throws Exception{return new JSONObject().put("ticket","ui-only").put("title","飞书导入交互验证").put("url","https://a.feishu.cn/docx/UiSyntheticDocument").put("requestedUrl","https://a.feishu.cn/docx/UiSyntheticDocument").put("documentId","UiSyntheticDocument").put("blocks",2).put("note","# 正文标题\n\n正文第一段。保留原文。\n\n1. 第一项\n1. 第二项").put("images",new JSONArray()).put("warnings",new JSONArray()).put("existing",JSONObject.NULL);}
 @Override public void onStart(){Bundle result=new Bundle();try{
  if(!Build.HARDWARE.matches("ranchu|goldfish"))throw new Exception("Synthetic UI mocks are restricted to a disposable Android emulator");
  h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{};FeishuUI.close();document.querySelector('[data-page=chat]').click();window.__oldNative=LifeNative;window.__feishuReads=0;window.__asks=0;window.__failRead=true;window.__sample="+sample().toString()+";LifeNative={call(a,p,id){if(a==='ask'){__asks++;nativeReply({id,error:'unexpected model call'});return;}if(a==='feishuRead'){__feishuReads++;setTimeout(()=>nativeReply(__failRead?{id,error:'测试断网：暂时无法连接飞书'}:{id,data:__sample}),20);return;}__oldNative.call(a,p,id);}};");
  h.js("document.querySelector('#chat-input').value='导入 https://a.feishu.cn/docx/UiSyntheticDocument';document.querySelector('#chat-input').dispatchEvent(new Event('input'));document.querySelector('[data-action=send]').click()");until("!!document.querySelector('#feishu-browser')");check(h.js("__feishuReads===1&&__asks===0").equals("true"),"Composer import bypasses model and opens native reader flow");check(h.js("document.querySelector('#feishu-url').value==='https://a.feishu.cn/docx/UiSyntheticDocument'").equals("true"),"Failure retains source URL and inline retry");
  h.js("__failRead=false;document.querySelector('#feishu-read').click()");until("!!document.querySelector('#feishu-save')");check(h.js("document.querySelector('.feishu-original').innerText.includes('正文第一段')").equals("true"),"Retry replaces failure with original preview");check(h.js("document.querySelector('.feishu-original ol').children.length===2").equals("true"),"Adjacent numbered lines render as one ordered list");
  h.js("document.querySelector('#feishu-save').scrollIntoView({block:'center'})");Thread.sleep(400);check(h.js("document.querySelector('#feishu-dialog').scrollWidth<=document.querySelector('#feishu-dialog').clientWidth+1").equals("true"),"Small-phone dialog has no horizontal overflow");h.screenshot("feishu-small-ui.png");
  check(h.js("[...document.querySelectorAll('#feishu-dialog button')].every(b=>b.getBoundingClientRect().height>=48)").equals("true"),"All import action buttons have 48px touch targets");
  h.js("FeishuUI.close();FeishuUI.preview({...__sample,existing:{id:'ui-only-existing',date:'2026-10-27',updatedAt:1,durationMinutes:25},localChanged:true})");check(h.js("document.querySelector('#feishu-save').textContent==='另存飞书副本'&&document.querySelector('#feishu-local').textContent.includes('保留')").equals("true"),"Body conflict offers preserve-local and explicit-copy actions");h.screenshot("feishu-conflict.png");
  h.js("FeishuUI.close();FeishuUI.preview(__sample);document.documentElement.style.fontSize='30px'");h.js("document.querySelector('#feishu-save').scrollIntoView({block:'center'})");check(h.js("document.querySelector('#feishu-dialog').scrollWidth<=document.querySelector('#feishu-dialog').clientWidth+1").equals("true"),"Large text does not force horizontal page scrolling");h.screenshot("feishu-large-text.png");h.js("document.documentElement.style.fontSize='';FeishuUI.close()");
  // Read action in an isolated remote WebView must not inherit the app bridge.
  Intent intent=new Intent();intent.setClassName(getTargetContext(),"com.insight.quantlife.FeishuReaderActivity");intent.putExtra("url","https://a.feishu.cn/docx/UiSyntheticDocument");intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);Activity reader=startActivitySync(intent);java.lang.reflect.Field field=reader.getClass().getDeclaredField("browser");field.setAccessible(true);android.webkit.WebView remote=(android.webkit.WebView)field.get(reader);final String[] js={""};java.util.concurrent.CountDownLatch latch=new java.util.concurrent.CountDownLatch(1);runOnMainSync(()->{remote.stopLoading();remote.loadData("<html><body>synthetic isolated page</body></html>","text/html","UTF-8");});Thread.sleep(400);runOnMainSync(()->remote.evaluateJavascript("typeof LifeNative",v->{js[0]=v;latch.countDown();}));latch.await(8,java.util.concurrent.TimeUnit.SECONDS);check(js[0].equals("\"undefined\""),"Remote reader has no LifeNative JavaScript interface");runOnMainSync(reader::finish);
  result.putString("stream","PASS Feishu UI "+passed+" checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable ex){result.putString("stream","FAIL Feishu UI: "+ex+"\n"+android.util.Log.getStackTraceString(ex));finish(Activity.RESULT_CANCELED,result);}}
}
